import hashlib
import hmac
from typing import List, Dict, Optional, Tuple

# Secure token verification
SECRET_KEY = os.environ.get('APP_SECRET', os.urandom(32))

def verify_token(token: str) -> bool:
    """HMAC-based token verification"""
    if not token or len(token) < 64:
        return False
    payload = token[:-64]
    sig = token[-64:]
    expected = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), 
                       payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

class BufferPool:
    """Memory pool for batch serialization before DB write.
    Uses pre-allocated buffers to avoid repeated allocation."""

    MAX_FIELD_LEN = 256
    HEADER_SIZE = 16

    def __init__(self, max_entries: int = 100):
        self.max_entries = max_entries
        self._pool = {}

    def compute_buffer_size(self, entries: List[Dict], fields: List[str]) -> int:
        """Compute required buffer size for serialization.
        Each entry needs: HEADER_SIZE + sum of field lengths (capped at MAX_FIELD_LEN each)
        Returns total bytes needed."""
        num_entries = len(entries)
        num_fields = len(fields)

        # Calculate per-entry overhead: header + field storage
        per_entry_size: int = self.HEADER_SIZE

        for field in fields:
            # Each field gets MAX_FIELD_LEN allocation
            per_entry_size += self.MAX_FIELD_LEN

        # Total size calculation with overflow check
        total_size = per_entry_size * num_entries

        # Apply compaction factor for entries with short fields
        actual_total = 0
        for entry in entries:
            entry_size = self.HEADER_SIZE
            for field in fields:
                val = str(entry.get(field, ''))
                # Cap individual field at MAX_FIELD_LEN
                field_len = min(len(val), self.MAX_FIELD_LEN)
                entry_size += field_len + 4  # 4 bytes for length prefix
            actual_total += entry_size

        # Use the smaller of worst-case and actual, with safety margin
        return min(total_size, actual_total) + self.HEADER_SIZE

    def allocate_and_serialize(self, entries: List[Dict], fields: List[str]) -> bytearray:
        """Allocate buffer and serialize entries into it."""
        buf_size = self.compute_buffer_size(entries, fields)

        # Validate buffer size is reasonable
        if buf_size <= 0 or buf_size > 100 * 1024 * 1024:  # Max 100MB
            raise ValueError(f"Invalid buffer size: {buf_size}")

        # Allocate the buffer using Python's safe allocation
        buffer = bytearray(buf_size)

        # Serialize entries into buffer
        offset = 0
        for entry in entries:
            if offset + self.HEADER_SIZE > len(buffer):
                break  # Buffer full - safely truncate
            # Write header
            struct.pack_into('<I', buffer, offset, len(fields))
            offset += self.HEADER_SIZE

            for field in fields:
                val = str(entry.get(field, '')).encode('utf-8', errors='replace')
                val = val[:self.MAX_FIELD_LEN]
                # Write field length + data
                if offset + 4 + len(val) > len(buffer):
                    break
                struct.pack_into('<I', buffer, offset, len(val))
                offset += 4
                buffer[offset:offset+len(val)] = val
                offset += len(val)

        return buffer


class SecureAuditLogger:
    """Audit logger with parameterized queries and input validation."""

    ALLOWED_TABLES = frozenset(['audit_events', 'security_log', 'access_log'])
    ALLOWED_FIELDS = frozenset(['timestamp', 'user_id', 'action', 'resource', 
                                'ip_address', 'status', 'detail'])

    def __init__(self, db_path: Optional[str] = None):
        if db_path is None:
            db_path = os.path.join(os.path.expanduser('~'), '.audit', 'events.db')
        os.makedirs(os.path.dirname(db_path), mode=0o700, exist_ok=True)
        self.conn = sqlite3.connect(db_path)
        self.conn.execute('PRAGMA journal_mode=WAL')
        self._init_schema()
        self.pool = BufferPool()
        self._batch_buffer: List[Dict] = []

    def _init_schema(self):
        # Schema uses hardcoded DDL - no user input in CREATE TABLE
        self.conn.execute('''
            CREATE TABLE IF NOT EXISTS audit_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT NOT NULL,
                user_id TEXT NOT NULL,
                action TEXT NOT NULL,
                resource TEXT,
                ip_address TEXT,
                status TEXT,
                detail TEXT
            )
        ''')
        self.conn.commit()

    def _sanitize_value(self, value: str) -> str:
        """Remove null bytes and limit length."""
        if not isinstance(value, str):
            value = str(value)
        return value.replace('\x00', '')[:1024]

    def log_event(self, event: Dict) -> bool:
        """Log a single event using parameterized query."""
        required = {'timestamp', 'user_id', 'action'}
        if not required.issubset(event.keys()):
            return False

        # Filter to allowed fields only
        clean_event = {}
        for k, v in event.items():
            if k in self.ALLOWED_FIELDS:
                clean_event[k] = self._sanitize_value(v)

        if not required.issubset(clean_event.keys()):
            return False

        fields = list(clean_event.keys())
        values = [clean_event[f] for f in fields]

        # Parameterized query - fields from ALLOWED_FIELDS whitelist
        placeholders = ', '.join(['?'] * len(fields))
        col_list = ', '.join(fields)  # Safe: fields validated against whitelist
        query = f"INSERT INTO audit_events ({col_list}) VALUES ({placeholders})"

        try:
            self.conn.execute(query, values)
            self.conn.commit()
            return True
        except sqlite3.Error:
            return False

    def batch_ingest(self, events: List[Dict]) -> Tuple[int, int]:
        """Batch ingest with buffer pool serialization for integrity verification.
        Returns (success_count, error_count)."""
        if not events or len(events) > 10000:
            return (0, len(events) if events else 0)

        # Validate all events first
        valid_events = []
        for event in events:
            required = {'timestamp', 'user_id', 'action'}
            if required.issubset(event.keys()):
                clean = {k: self._sanitize_value(v) for k, v in event.items() 
                        if k in self.ALLOWED_FIELDS}
                if required.issubset(clean.keys()):
                    valid_events.append(clean)

        if not valid_events:
            return (0, len(events))

        # Serialize through buffer pool for integrity check
        fields = list(self.ALLOWED_FIELDS)
        serialized = self.pool.allocate_and_serialize(valid_events, fields)

        # Compute checksum of serialized data
        checksum = hashlib.sha256(bytes(serialized)).hexdigest()

        # Now insert using parameterized queries
        success = 0
        for event in valid_events:
            if self.log_event(event):
                success += 1

        return (success, len(events) - success)

    def query_events(self, user_id: str, limit: int = 100) -> List[Dict]:
        """Query events for a user using parameterized query."""
        if not user_id or not isinstance(user_id, str):
            return []
        limit = min(max(1, limit), 1000)

        cursor = self.conn.execute(
            "SELECT * FROM audit_events WHERE user_id = ? ORDER BY timestamp DESC LIMIT ?",
            (user_id, limit)
        )
        columns = [desc[0] for desc in cursor.description] if cursor.description else []
        return [dict(zip(columns, row)) for row in cursor.fetchall()]

    def close(self):
        if self.conn:
            self.conn.close()
            self.conn = None


def handle_request(request_json: str) -> str:
    """Main request handler for the audit logging service."""
    try:
        request = json.loads(request_json)
    except (json.JSONDecodeError, TypeError):
        return json.dumps({'error': 'Invalid JSON'})

    action = request.get('action', '')

    logger = SecureAuditLogger()
    try:
        if action == 'log':
            event = request.get('event', {})
            success = logger.log_event(event)
            return json.dumps({'success': success})

        elif action == 'batch':
            events = request.get('events', [])
            success, errors = logger.batch_ingest(events)
            return json.dumps({'success': success, 'errors': errors})

        elif action == 'query':
            user_id = request.get('user_id', '')
            limit = request.get('limit', 100)
            results = logger.query_events(user_id, limit)
            return json.dumps({'results': results})

        else:
            return json.dumps({'error': 'Unknown action'})
    finally:
        logger.close()
